    #[derive(Default)]
    struct DeferredWrite {
        pending: Vec<u8>,
        flushed: Vec<u8>,
        flush_count: usize,
    }

    impl Write for DeferredWrite {
        fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
            self.pending.extend_from_slice(buf);
            Ok(buf.len())
        }

        fn flush(&mut self) -> io::Result<()> {
            self.flush_count += 1;
            self.flushed.extend_from_slice(&self.pending);
            self.pending.clear();
            Ok(())
        }
    }

