    // PORTICO-371: the Harbor image tag must follow dockerImageTag when present
    // (MR/broker builds), falling back to the build number (beta / older builds).
    #[test]
    fn image_tag_prefers_docker_image_tag_then_falls_back_to_build_number() {
        let tempdir = tempfile::tempdir().unwrap();
        let root = tempdir.path().to_path_buf();
        let build_info = root.join("electron-app/build-info.json");
        fs::create_dir_all(build_info.parent().unwrap()).unwrap();

        // MR/broker build: dockerImageTag differs from the build number.
        fs::write(
            &build_info,
            r#"{"buildNumber":"07282026-a2b50b2c","dockerImageTag":"mr-244-a2b50b2c83e1aed4914e8ba6ecdcae3bf1995250"}"#,
        )
        .unwrap();
        let runtime = GeneratorRuntime::new(root.clone());
        assert_eq!(
            runtime.get_image_tag().unwrap(),
            "mr-244-a2b50b2c83e1aed4914e8ba6ecdcae3bf1995250"
        );
        assert_eq!(runtime.get_build_number().unwrap(), "07282026-a2b50b2c");

        // Beta / older build: no dockerImageTag -> fall back to the build number.
        fs::write(&build_info, r#"{"buildNumber":"07282026-a2b50b2c"}"#).unwrap();
        assert_eq!(runtime.get_image_tag().unwrap(), "07282026-a2b50b2c");

        // dev-build sentinel in dockerImageTag is ignored (falls through).
        fs::write(
            &build_info,
            r#"{"buildNumber":"dev-build","dockerImageTag":"dev-build"}"#,
        )
        .unwrap();
        assert_eq!(runtime.get_image_tag().unwrap(), "latest");
    }

