    #[test]
    fn runtime_file_helpers_validate_sources_and_filenames() {
        let tempdir = tempfile::tempdir().unwrap();
        let source = tempdir.path().join("mcp_config.yaml");
        fs::write(&source, "snowflake: true\n").unwrap();
        let directory = tempdir.path().join("config-dir");
        fs::create_dir_all(&directory).unwrap();

        let resolved =
            resolve_runtime_file_source(tempdir.path(), "mcp_config.yaml").expect("resolve file");
        assert_eq!(resolved, source.canonicalize().unwrap());
        assert_eq!(
            runtime_file_filename(&resolved, None).unwrap(),
            "mcp_config.yaml"
        );
        assert_eq!(
            runtime_file_filename(&resolved, Some("renamed.yaml")).unwrap(),
            "renamed.yaml"
        );
        assert_eq!(
            runtime_file_target_path(&resolved, None, None).unwrap(),
            "/app/runtime/mcp_config.yaml"
        );
        assert_eq!(
            runtime_file_target_path(&resolved, Some("renamed.yaml"), None).unwrap(),
            "/app/runtime/renamed.yaml"
        );
        assert_eq!(
            runtime_file_target_path(&resolved, None, Some("/root/.snowflake/connections.toml"))
                .unwrap(),
            "/root/.snowflake/connections.toml"
        );
        assert!(resolve_runtime_file_source(tempdir.path(), "missing.yaml").is_err());
        assert!(resolve_runtime_file_source(tempdir.path(), "config-dir").is_err());
        assert!(runtime_file_filename(&resolved, Some("../escape.yaml")).is_err());
        assert!(runtime_file_filename(&resolved, Some("nested/escape.yaml")).is_err());
        assert!(runtime_file_target_path(
            &resolved,
            Some("mcp_config.yaml"),
            Some("/root/config.toml")
        )
        .is_err());
        assert!(runtime_file_target_path(&resolved, None, Some("relative/config.toml")).is_err());
        assert!(runtime_file_target_path(&resolved, None, Some("/root/../config.toml")).is_err());
        assert!(runtime_file_target_path(&resolved, None, Some("/root\\config.toml")).is_err());
        assert!(runtime_file_target_path(&resolved, None, Some("/root/config:toml")).is_err());
        assert!(runtime_file_target_path(&resolved, None, Some("/root/.snowflake/")).is_err());
    }

    #[test]
    fn unreadable_runtime_file_is_an_attributed_not_configured_issue() {
        let tempdir = tempfile::tempdir().unwrap();
        let source = tempdir.path().join("mcp_config.yaml");
        fs::write(&source, "snowflake: true\n").unwrap();
        fs::set_permissions(&source, fs::Permissions::from_mode(0o000)).unwrap();

        let issue = super::runtime_file_configuration_issue(
            tempdir.path(),
            "snowflake",
            &[RuntimeFileMount {
                source: source.to_string_lossy().to_string(),
                filename: None,
                target: Some("/root/.snowflake/mcp_config.yaml".to_string()),
                sensitive: false,
                sensitive_raw: None,
            }],
        )
        .unwrap()
        .expect("permission denial must produce a per-server issue");

        // Restore access before TempDir cleanup.
        fs::set_permissions(&source, fs::Permissions::from_mode(0o600)).unwrap();
        assert_eq!(issue.error_code, "RUNTIME_FILE_PERMISSION_DENIED");
        assert!(issue.reason.contains("permission denied"));
        let status = super::runtime_file_status_entry_from_issue(&issue);
        assert!(!status.configured);
        assert_eq!(status.status, "not_configured");
        assert_eq!(
            status.error_code.as_deref(),
            Some("RUNTIME_FILE_PERMISSION_DENIED")
        );
    }

