    #[test]
    fn retryable_tools_propagate_through_shared_and_isolated_config_paths() {
        let tempdir = tempfile::tempdir().unwrap();
        let root = tempdir.path();
        let yaml = root.join("demo.yaml");
        let fragment = root.join("demo.fragment");
        let output = root.join("demo.json");
        fs::write(
            &yaml,
            "retryable_tools:\n  - originalRead\n  - anotherRead\ntool_rename_mapping:\n  Originalread: Renamed Read\n",
        )
        .unwrap();
        fs::write(&fragment, r#"{"command":"uvx","args":["demo"]}"#).unwrap();

        let mut runtime = GeneratorRuntime::new(root.to_path_buf());
        let mut stdout = Vec::new();
        let mut stderr = Vec::new();
        let mut emitter = Emitter::new(&mut stdout, &mut stderr);
        let shared = runtime
            .process_fragment(&fragment, "demo", Some(&yaml), &mut emitter)
            .unwrap();
        assert_eq!(
            shared["retryable_tools"],
            serde_json::json!(["originalRead", "anotherRead"])
        );
        assert_eq!(
            shared["tool_rename_mapping"]["Originalread"],
            "Renamed Read"
        );

        runtime
            .generate_server_config("demo", &fragment, &yaml, &output)
            .unwrap();
        let isolated: serde_json::Value =
            serde_json::from_str(&fs::read_to_string(output).unwrap()).unwrap();
        assert_eq!(
            isolated["mcpServers"]["demo"]["retryable_tools"],
            shared["retryable_tools"]
        );
    }

