    #[test]
    fn generate_docker_service_omits_slack_oauth_client_secret_ingress() {
        let tempdir = tempfile::tempdir().unwrap();
        let root = tempdir.path();
        let server_id = "slack";
        let server_dir = root.join("mcp-configs").join(server_id);
        fs::create_dir_all(&server_dir).unwrap();
        fs::write(root.join(".env"), "").unwrap();
        let yaml = server_dir.join(format!("{server_id}.yaml"));
        fs::write(
            &yaml,
            concat!(
                "name: Slack MCP Server\n",
                "id: slack\n",
                "display_name: Slack\n",
                "deployment_type: docker\n",
                "description: Slack\n",
                "user_installed: false\n",
                "is_core: false\n",
                "required_env_vars: []\n",
            ),
        )
        .unwrap();
        let fragment = server_dir.join(format!("{server_id}.fragment"));
        fs::write(
            &fragment,
            "{\n  \"command\": \"/app/mcp-servers/slack-mcp-server\",\n  \"args\": []\n}\n",
        )
        .unwrap();

        let mut runtime = GeneratorRuntime::new(root.to_path_buf());
        let service = runtime
            .generate_docker_service(server_id, &fragment, &yaml, "regular")
            .unwrap();

        assert!(
            !service.contains("SLACK_OAUTH_CLIENT_ID_FILE"),
            "slack PKCE service must not mount legacy client id secret:\n{service}"
        );
        assert!(
            !service.contains("SLACK_OAUTH_CLIENT_SECRET_FILE"),
            "slack PKCE service must not mount legacy client secret:\n{service}"
        );
        assert!(
            !service.contains("slack_oauth_client_"),
            "slack PKCE service must not declare legacy oauth client secrets:\n{service}"
        );
        assert!(
            service.contains("slack-mcp-cache:/root/.cache/slack-mcp-server"),
            "dedicated Slack runtime must persist its identity-scoped cache:\n{service}"
        );
        assert!(
            service.contains(
                "${PORTICO_APP_SUPPORT_DIR:-./open-webui-data/app-support}/slack-mcp-state:/app/slack-mcp-state:rw"
            ),
            "dedicated Slack runtime must mount the host-editable sync-state dir:\n{service}"
        );
        assert!(
            !service.contains("users_seed_v1.json.gz"),
            "seed mount must be absent when the release carried no seed artifact:\n{service}"
        );
        assert!(
            !service.contains("channels_seed_v1.json.gz"),
            "channels seed mount must be absent when the release carried none:\n{service}"
        );
    }

