    #[test]
    fn generate_docker_service_wires_oauth_access_token_broker_env_only_for_oauth_servers() {
        let tempdir = tempfile::tempdir().unwrap();
        let root = tempdir.path();
        fs::write(root.join(".env"), "").unwrap();

        for (server_id, fragment, yaml_oauth) in [
            (
                "oauth-demo",
                r#"{"command":"uvx","args":["oauth-demo"],"oauth":{"authorization_server":"https://auth.example.test"}}"#,
                "",
            ),
            (
                "yaml-oauth-demo",
                r#"{"command":"uvx","args":["yaml-oauth-demo"]}"#,
                "oauth:\n  requires_user_authorization: true\n",
            ),
            (
                "dynamic-oauth-demo",
                r#"{"type":"streamable-http","url":"https://mcp.example.test/mcp"}"#,
                "",
            ),
            (
                "plain-demo",
                r#"{"command":"uvx","args":["plain-demo"]}"#,
                "",
            ),
        ] {
            let server_dir = root.join("mcp-configs").join(server_id);
            fs::create_dir_all(&server_dir).unwrap();
            fs::write(
                server_dir.join(format!("{server_id}.yaml")),
                format!(
                    "name: {server_id}\nid: {server_id}\ndisplay_name: {server_id}\ndeployment_type: docker\ndescription: {server_id}\nuser_installed: false\nis_core: false\nrequired_env_vars: []\n{yaml_oauth}"
                ),
            )
            .unwrap();
            fs::write(server_dir.join(format!("{server_id}.fragment")), fragment).unwrap();
        }

        let mut runtime = GeneratorRuntime::new(root.to_path_buf());
        let oauth_service = runtime
            .generate_docker_service(
                "oauth-demo",
                &root.join("mcp-configs/oauth-demo/oauth-demo.fragment"),
                &root.join("mcp-configs/oauth-demo/oauth-demo.yaml"),
                "regular",
            )
            .unwrap();
        assert!(oauth_service.contains(
            "portico_OAUTH_ACCESS_TOKEN_BROKER_URL=${portico_OAUTH_ACCESS_TOKEN_BROKER_URL:-http://host.docker.internal:8891/secrets/oauth/access-token}"
        ));
        assert!(oauth_service.contains("portico_OAUTH_ACCESS_TOKEN_SERVER_ID=oauth-demo"));
        assert!(oauth_service.contains(
            "portico_OAUTH_ACCESS_TOKEN_BROKER_TOKEN=${portico_OAUTH_ACCESS_TOKEN_TOKEN_OAUTH_DEMO:-}"
        ));
        assert!(!oauth_service.contains("mcpo-oauth-tokens"));
        assert!(!oauth_service.contains("/root/.mcpo"));

        let yaml_oauth_service = runtime
            .generate_docker_service(
                "yaml-oauth-demo",
                &root.join("mcp-configs/yaml-oauth-demo/yaml-oauth-demo.fragment"),
                &root.join("mcp-configs/yaml-oauth-demo/yaml-oauth-demo.yaml"),
                "regular",
            )
            .unwrap();
        assert!(yaml_oauth_service.contains("portico_OAUTH_ACCESS_TOKEN_SERVER_ID=yaml-oauth-demo"));
        assert!(yaml_oauth_service.contains(
            "portico_OAUTH_ACCESS_TOKEN_BROKER_TOKEN=${portico_OAUTH_ACCESS_TOKEN_TOKEN_YAML_OAUTH_DEMO:-}"
        ));

        let dynamic_oauth_service = runtime
            .generate_docker_service(
                "dynamic-oauth-demo",
                &root.join("mcp-configs/dynamic-oauth-demo/dynamic-oauth-demo.fragment"),
                &root.join("mcp-configs/dynamic-oauth-demo/dynamic-oauth-demo.yaml"),
                "regular",
            )
            .unwrap();
        assert!(
            dynamic_oauth_service.contains("portico_OAUTH_ACCESS_TOKEN_SERVER_ID=dynamic-oauth-demo")
        );
        assert!(dynamic_oauth_service.contains(
            "portico_OAUTH_ACCESS_TOKEN_BROKER_TOKEN=${portico_OAUTH_ACCESS_TOKEN_TOKEN_DYNAMIC_OAUTH_DEMO:-}"
        ));

        let plain_service = runtime
            .generate_docker_service(
                "plain-demo",
                &root.join("mcp-configs/plain-demo/plain-demo.fragment"),
                &root.join("mcp-configs/plain-demo/plain-demo.yaml"),
                "regular",
            )
            .unwrap();
        assert!(!plain_service.contains("portico_OAUTH_ACCESS_TOKEN_BROKER_URL"));
        assert!(!plain_service.contains("portico_OAUTH_ACCESS_TOKEN_SERVER_ID"));
        assert!(!plain_service.contains("portico_OAUTH_ACCESS_TOKEN_BROKER_TOKEN"));
    }

    #[test]
    fn generate_docker_service_wires_sensitive_non_sensitive_and_preset_envs() {
        let tempdir = tempfile::tempdir().unwrap();
        let root = tempdir.path();
        let server_id = "env-matrix";
        let server_dir = root.join("mcp-configs").join(server_id);
        fs::create_dir_all(&server_dir).unwrap();
        fs::write(root.join(".env"), "").unwrap();
        let yaml = server_dir.join(format!("{server_id}.yaml"));
        fs::write(
            &yaml,
            concat!(
                "name: Env Matrix\n",
                "id: env-matrix\n",
                "display_name: Env Matrix\n",
                "deployment_type: docker\n",
                "description: Env matrix\n",
                "user_installed: false\n",
                "is_core: false\n",
                "required_env_vars:\n",
                "- description: Figma personal access token\n",
                "  name: MATRIX_SECRET\n",
                "  sensitive: true\n",
                "- name: MATRIX_PUBLIC\n",
                "  sensitive: false\n",
                "- name: MATRIX_DEFAULT\n",
                "- MATRIX_LEGACY\n",
                "preset_env_vars:\n",
                "- name: MATRIX_PRESET\n",
                "  value: preset value\n",
                "- name: MATRIX_PUBLIC\n",
                "  value: preset-must-not-duplicate-fragment\n",
            ),
        )
        .unwrap();
        let fragment = server_dir.join(format!("{server_id}.fragment"));
        fs::write(
            &fragment,
            "{\n  \"command\": \"uvx\",\n  \"args\": [\"demo\"],\n  \"env\": {\"MATRIX_SECRET\": \"${MATRIX_SECRET}\", \"MATRIX_PUBLIC\": \"fragment-public\"}\n}\n",
        )
        .unwrap();

        let mut runtime = GeneratorRuntime::new(root.to_path_buf());
        let metadata = runtime.yaml_metadata(&yaml).unwrap().clone();
        assert_eq!(
            metadata.required_env_vars,
            vec![
                RequiredEnvVar {
                    name: "MATRIX_SECRET".to_string(),
                    sensitive: true,
                    placeholder: None,
                    description: Some("Figma personal access token".to_string()),
                },
                RequiredEnvVar {
                    name: "MATRIX_PUBLIC".to_string(),
                    sensitive: false,
                    placeholder: None,
                    description: None,
                },
                RequiredEnvVar {
                    name: "MATRIX_DEFAULT".to_string(),
                    sensitive: false,
                    placeholder: None,
                    description: None,
                },
                RequiredEnvVar {
                    name: "MATRIX_LEGACY".to_string(),
                    sensitive: false,
                    placeholder: None,
                    description: None,
                },
            ]
        );
        assert_eq!(
            metadata.preset_env_vars,
            vec![
                PresetEnvVar {
                    name: "MATRIX_PRESET".to_string(),
                    value: "preset value".to_string(),
                },
                PresetEnvVar {
                    name: "MATRIX_PUBLIC".to_string(),
                    value: "preset-must-not-duplicate-fragment".to_string(),
                },
            ]
        );

        let service = runtime
            .generate_docker_service(server_id, &fragment, &yaml, "regular")
            .unwrap();

        assert!(service.contains("MATRIX_SECRET_FILE=/dev/shm/portico-runtime-secrets/matrix_secret"));
        assert!(service.contains(
            "portico_STATIC_SECRET_TARGETS=env-matrix|matrix_secret|/dev/shm/portico-runtime-secrets/matrix_secret|portico_STATIC_SECRET_TOKEN_ENV_MATRIX_MATRIX_SECRET|"
        ));
        assert!(service.contains(
            "portico_STATIC_SECRET_TOKEN_ENV_MATRIX_MATRIX_SECRET=${portico_STATIC_SECRET_TOKEN_ENV_MATRIX_MATRIX_SECRET:-}"
        ));
        assert!(service.contains("    tmpfs:\n      - /dev/shm/portico-runtime-secrets:mode=0700"));
        assert!(!service.contains("      - matrix_secret"));
        assert!(!service.contains("MATRIX_SECRET=${MATRIX_SECRET}"));
        assert!(service.contains("MATRIX_PUBLIC=fragment-public"));
        assert_eq!(service.matches("MATRIX_PUBLIC=").count(), 1);
        assert!(service.contains("MATRIX_DEFAULT=${MATRIX_DEFAULT}"));
        assert!(service.contains("MATRIX_LEGACY=${MATRIX_LEGACY}"));
        assert!(service.contains("MATRIX_PRESET=preset value"));
    }

