    #[test]
    fn process_regular_server_skips_enabled_missing_runtime_file_source() {
        let tempdir = tempfile::tempdir().unwrap();
        let root = tempdir.path();
        let server_id = "missing-runtime-source";
        let server_dir = root.join("mcp-configs-user").join(server_id);
        fs::create_dir_all(&server_dir).unwrap();
        fs::create_dir_all(root.join("mcpo-configs-generated")).unwrap();
        fs::write(root.join(".env"), "").unwrap();
        fs::write(
            root.join("mcp_toggles.json"),
            format!(r#"{{"{server_id}": true}}"#),
        )
        .unwrap();
        fs::write(
            server_dir.join(format!("{server_id}.yaml")),
            format!(
                concat!(
                    "name: Missing Runtime Source\n",
                    "id: {}\n",
                    "display_name: Missing Runtime Source\n",
                    "deployment_type: docker\n",
                    "description: Missing runtime file source\n",
                    "user_installed: true\n",
                    "is_core: false\n",
                    "required_env_vars: []\n",
                    "runtime_files:\n",
                    "- source: ./does-not-exist.yaml\n",
                ),
                server_id
            ),
        )
        .unwrap();
        fs::write(
            server_dir.join(format!("{server_id}.fragment")),
            "{\n  \"command\": \"uvx\",\n  \"args\": [\"demo\"]\n}\n",
        )
        .unwrap();

        let mut runtime = GeneratorRuntime::new(root.to_path_buf());
        let mut state = ComposeGenerationState::default();
        let mut stdout = Vec::new();
        let mut stderr = Vec::new();
        let mut emitter = Emitter::new(&mut stdout, &mut stderr);
        runtime
            .process_regular_server(&server_dir, "user", &mut state, &mut emitter)
            .unwrap();

        let stdout = String::from_utf8(stdout).unwrap();
        assert!(stdout.contains(
            "Skipping missing-runtime-source: not configured (missing runtime file: ./does-not-exist.yaml)"
        ));
        assert!(state.enabled_servers.is_empty());
        assert!(!state
            .docker_services
            .contains("mcpo-missing-runtime-source"));
        let status = state.runtime_file_statuses.get(server_id).unwrap();
        assert!(!status.configured);
        assert_eq!(status.status, "not_configured");
        assert_eq!(status.error_code.as_deref(), Some("RUNTIME_FILE_MISSING"));
        assert_eq!(status.source.as_deref(), Some("runtime_file"));
        assert_eq!(status.stage.as_deref(), Some("config_generation"));
        let server_status = state.server_config_statuses.get(server_id).unwrap();
        assert!(!server_status.configured);
        assert_eq!(server_status.status, "not_configured");
        assert_eq!(server_status.error, status.error);
        assert_eq!(
            server_status.error_code.as_deref(),
            Some("RUNTIME_FILE_MISSING")
        );
        assert_eq!(server_status.source.as_deref(), Some("runtime_file"));
        assert_eq!(server_status.stage.as_deref(), Some("config_generation"));
    }

    #[test]
    fn config_generation_quarantines_invalid_enabled_user_recipe_and_keeps_healthy_server() {
        let tempdir = tempfile::tempdir().unwrap();
        let root = tempdir.path();
        let user_configs = root.join("mcp-configs-user");
        let broken_id = "broken-node-recipe";
        let healthy_id = "healthy-server";
        let disabled_id = "disabled-invalid-server";
        fs::create_dir_all(&user_configs).unwrap();
        fs::write(
            root.join("mcp_toggles.json"),
            format!(r#"{{"{broken_id}":true,"{healthy_id}":true,"{disabled_id}":false}}"#),
        )
        .unwrap();

        for server_id in [broken_id, healthy_id, disabled_id] {
            let server_dir = user_configs.join(server_id);
            fs::create_dir_all(&server_dir).unwrap();
            fs::write(
                server_dir.join(format!("{server_id}.yaml")),
                format!(
                    "name: {server_id}\nid: {server_id}\ndeployment_type: docker\nuser_installed: true\nis_core: false\nrequired_env_vars: []\n"
                ),
            )
            .unwrap();
        }
        fs::write(
            user_configs
                .join(broken_id)
                .join(format!("{broken_id}.fragment")),
            r#"{"command":"npm","args":["start"]}"#,
        )
        .unwrap();
        fs::write(
            user_configs
                .join(healthy_id)
                .join(format!("{healthy_id}.fragment")),
            r#"{"command":"uvx","args":["healthy-mcp"]}"#,
        )
        .unwrap();
        // This would fail JSON parsing if the disabled server were inspected.
        fs::write(
            user_configs
                .join(disabled_id)
                .join(format!("{disabled_id}.fragment")),
            "not-json",
        )
        .unwrap();

        let mut runtime = GeneratorRuntime::new(root.to_path_buf());
        let mut state = super::ConfigGenerationState::default();
        let mut stdout = Vec::new();
        let mut stderr = Vec::new();
        let mut emitter = Emitter::new(&mut stdout, &mut stderr);
        runtime
            .process_config_server_directory(
                &user_configs,
                "user-installed",
                true,
                &mut state,
                &mut emitter,
            )
            .unwrap();

        assert_eq!(
            state
                .docker_entries
                .iter()
                .map(|(server_id, _)| server_id.as_str())
                .collect::<Vec<_>>(),
            vec![healthy_id]
        );
        let broken_status = state.server_config_statuses.get(broken_id).unwrap();
        assert!(!broken_status.configured);
        assert_eq!(
            broken_status.error_code.as_deref(),
            Some("UNSUPPORTED_NPM_SUBCOMMAND")
        );
        assert_eq!(broken_status.status, "not_configured");
        let healthy_status = state.server_config_statuses.get(healthy_id).unwrap();
        assert!(healthy_status.configured);
        assert_eq!(healthy_status.status, "configured");
        assert!(healthy_status.error.is_empty());
        assert!(!state.server_config_statuses.contains_key(disabled_id));
    }

