    #[test]
    fn malformed_enabled_user_yaml_is_quarantined_and_removes_stale_output() {
        let tempdir = tempfile::tempdir().unwrap();
        let root = tempdir.path();
        let server_id = "malformed-user";
        let server_dir = root.join("mcp-configs-user").join(server_id);
        fs::create_dir_all(root.join("mcp-configs")).unwrap();
        fs::create_dir_all(&server_dir).unwrap();
        fs::write(root.join(".env"), "").unwrap();
        fs::write(
            root.join("mcp_toggles.json"),
            format!(r#"{{"{server_id}":true}}"#),
        )
        .unwrap();
        fs::write(
            server_dir.join(format!("{server_id}.yaml")),
            format!(
                "name: {server_id}\nid: {server_id}\ndeployment_type: docker\nuser_installed: true\nis_core: false\nrequired_env_vars: []\n"
            ),
        )
        .unwrap();
        fs::write(
            server_dir.join(format!("{server_id}.fragment")),
            r#"{"command":"uvx","args":["healthy-mcp"]}"#,
        )
        .unwrap();

        let mut stdout = Vec::new();
        let mut stderr = Vec::new();
        {
            let mut emitter = Emitter::new(&mut stdout, &mut stderr);
            let mut runtime = GeneratorRuntime::new(root.to_path_buf());
            runtime
                .run_docker_compose_override(false, &mut emitter)
                .unwrap();
        }
        let generated = root
            .join("mcpo-configs-generated")
            .join(format!("{server_id}.json"));
        assert!(generated.is_file());
        let configured_status: serde_json::Value = serde_json::from_slice(
            &fs::read(root.join("mcpo-configs-generated/server-config-status.json")).unwrap(),
        )
        .unwrap();
        assert_eq!(configured_status["servers"][server_id]["configured"], true);
        assert_eq!(
            configured_status["servers"][server_id]["status"],
            "configured"
        );
        assert_eq!(configured_status["servers"][server_id]["error"], "");

        fs::write(
            server_dir.join(format!("{server_id}.yaml")),
            "display_name: [unterminated\n",
        )
        .unwrap();
        stdout.clear();
        stderr.clear();
        {
            let mut emitter = Emitter::new(&mut stdout, &mut stderr);
            let mut runtime = GeneratorRuntime::new(root.to_path_buf());
            runtime
                .run_docker_compose_override(false, &mut emitter)
                .unwrap();
        }

        assert!(!generated.exists());
        let status: serde_json::Value = serde_json::from_slice(
            &fs::read(root.join("mcpo-configs-generated/server-config-status.json")).unwrap(),
        )
        .unwrap();
        assert_eq!(status["servers"][server_id]["configured"], false);
        assert_eq!(status["servers"][server_id]["status"], "not_configured");
        assert_eq!(
            status["servers"][server_id]["error_code"],
            "INVALID_USER_SERVER_CONFIG"
        );
    }

